INSERT INTO Manuales (id_manual, dirigido_a, seccion_software, contenido_texto, fecha_actualizacion, id_usuario_edito, contenido_enlace) VALUES
    (1, 'Administrador RH', 'Inicio de sesión', 'Escriba su usuario y contraseña y pulse "Iniciar sesión". \nEn el primer inicio de sesión, o después de un restablecimiento, el sistema pide una contraseña nueva de al menos 8 caracteres con una mayúscula, una minúscula y un número. \nTras 5 intentos fallidos la cuenta se bloquea 15 minutos. \nSi olvidó su usuario o contraseña, pulse "¿Olvidaste tu usuario o contraseña?", escriba su correo y el Administrador de RH se pondrá en contacto con usted.', '2026-10-07 14:39:12', 76, NULL),
    (2, 'Administrador RH', 'Paneles analíticos', 'Muestra los indicadores generales, la distribución por nivel de potencial, la matriz 9-box, el promedio de puntuación por área, el histograma de puntuaciones y la evolución mensual. Use los filtros de la parte superior para acotar los datos. Haga clic en un área o en una celda de la matriz 9-box para ver el detalle hasta llegar al perfil del talento.', '2026-10-11 20:29:37', 76, NULL),
    (3, 'Administrador RH', 'Reportes', 'Busque a un talento por ID o por nombre, o selecciónelo en la lista general. Desde su perfil puede exportar el reporte individual en PDF o Excel. El reporte general se genera con los filtros aplicados. Si el archivo no se puede generar, el sistema entrega un archivo de texto con los mismos datos.', '2026-10-11 20:31:17', 76, NULL),
    (4, 'Administrador RH', 'Historial y evolución', 'Seleccione a un talento para ver su línea de tiempo: la puntuación de la IA de cada evaluación en el eje vertical y la fecha en el horizontal, junto con sus eventos (promociones, capacitaciones, cambios de clasificación, etc.).', '2026-10-11 20:32:26', 76, NULL),
    (5, 'Administrador RH', 'Notificaciones', 'En "Bandeja" consulte sus notificaciones y su estado. En "Nueva notificación" elija el tipo, el talento (opcional), el grado de emergencia y escriba el texto. En "Alertas" configure reglas que generan notificaciones automáticas cuando cambian los indicadores de los talentos.', '2026-09-28 10:27:30', 76, NULL),
    (6, 'Administrador RH', 'Configuración', 'Cambie su foto de perfil (No mayor a 5MB), contraseña, el tema claro u oscuro, consulte el contacto de soporte o cierre sesión. El Administrador de RH además gestiona usuarios, parámetros del sistema, manuales y consulta la bitácora.', '2026-10-11 20:38:31', 76, NULL),
    (7, 'Administrador RH', 'Soporte', 'En la pestaña "Manuales" elija la sección del sistema o busque por texto. En "Contacto" encontrará los datos de soporte y el botón "Escribir correo"; si apareció un código de error, inclúyalo en el mensaje.', '2026-09-28 10:27:30', 76, NULL),
    (13, 'Administrador RH', 'Talentos', 'Busque a un talento por ID o por nombre, o filtre la lista por área. Al seleccionarlo verá sus datos y la pestaña "Evaluación con IA". El Administrador de RH da de alta talentos en "Nuevo talento", los edita, los da de baja con un motivo y los evalúa con el botón "Evaluar" (hay un número limitado de evaluaciones por talento al día). El Encargado de área consulta los talentos de su área y puede solicitar una corrección de datos o una reevaluación con IA.', '2026-09-30 20:26:04', 76, NULL),
    (14, 'Administrador RH', 'Gestión de usuarios', 'Dé de alta usuarios con su cargo y área; el sistema genera una contraseña temporal que se muestra una sola vez y debe comunicarse en persona. Desde la lista puede editar, desactivar o reactivar usuarios y restablecer su contraseña (también desbloquea la cuenta). En "Solicitudes" aparecen los pedidos de restablecimiento hechos desde el inicio de sesión.', '2026-09-30 20:26:04', 76, NULL),
    (15, 'Administrador RH', 'Parámetros del sistema', 'Modifique el contacto de soporte, el tiempo máximo y el número de evaluaciones diarias de la IA, la variación por defecto de las alertas, los intentos antes del bloqueo, los minutos de bloqueo y los minutos de inactividad. Pulse "Guardar": los cambios se aplican de inmediato y quedan en la bitácora.', '2026-09-30 20:26:04', 76, NULL),
    (16, 'Administrador RH', 'Bitácora', 'Consulte las acciones registradas en el sistema (inicios de sesión, altas, ediciones, bajas, evaluaciones, exportaciones y cambios de configuración). Filtre por fechas, usuario, acción y tabla. La bitácora no se puede editar ni borrar.', '2026-09-30 20:26:04', 76, NULL),
    (22, 'Encargado de area', 'Inicio de sesión', 'Escriba su usuario y contraseña y pulse "Iniciar sesión". \nEn el primer inicio de sesión, o después de un restablecimiento, el sistema pide una contraseña nueva de al menos 8 caracteres con una mayúscula, una minúscula y un número. \nTras 5 intentos fallidos la cuenta se bloquea 15 minutos. \nSi olvidó su usuario o contraseña, pulse "¿Olvidaste tu usuario o contraseña?", escriba su correo y el Administrador de RH se pondrá en contacto con usted.', '2026-10-07 14:39:12', 76, NULL),
    (23, 'Encargado de area', 'Paneles analíticos', 'Muestra los indicadores generales, la distribución por nivel de potencial, la matriz 9-box, el promedio de puntuación por área, el histograma de puntuaciones y la evolución mensual. Use los filtros de la parte superior para acotar los datos. Haga clic en un área o en una celda de la matriz 9-box para ver el detalle hasta llegar al perfil del talento.', '2026-10-11 21:25:03', 76, NULL),
    (24, 'Encargado de area', 'Reportes', 'Busque a un talento por ID o por nombre, o selecciónelo en la lista general. Desde su perfil puede exportar el reporte individual en PDF o Excel. El reporte general se genera con los filtros aplicados. Si el archivo no se puede generar, el sistema entrega un archivo de texto con los mismos datos.', '2026-10-11 21:26:02', 76, NULL),
    (25, 'Encargado de area', 'Historial y evolución', 'Seleccione a un talento para ver su línea de tiempo: la puntuación de la IA de cada evaluación en el eje vertical y la fecha en el horizontal, junto con sus eventos (promociones, capacitaciones, cambios de clasificación, etc.).', '2026-10-11 21:26:50', 76, NULL),
    (26, 'Encargado de area', 'Notificaciones', 'En "Bandeja" consulte sus notificaciones y su estado. En "Nueva notificación" elija el tipo, el talento (opcional), el grado de emergencia y escriba el texto. En "Alertas" configure reglas que generan notificaciones automáticas cuando cambian los indicadores de los talentos.', '2026-10-11 21:28:37', 76, NULL),
    (27, 'Encargado de area', 'Configuración', 'Cambie su foto de perfil (No mayor a 5MB), contraseña, el tema claro u oscuro, consulte el contacto de soporte o cierre sesión. El Administrador de RH además gestiona usuarios, parámetros del sistema, manuales y consulta la bitácora.', '2026-10-11 21:30:20', 76, NULL),
    (28, 'Encargado de area', 'Soporte', 'En la pestaña "Manuales" elija la sección del sistema o busque por texto. En "Contacto" encontrará los datos de soporte y el botón "Escribir correo"; si apareció un código de error, inclúyalo en el mensaje.', '2026-09-28 10:27:30', 76, NULL),
    (29, 'Encargado de area', 'Talentos', 'Busque a un talento por ID o por nombre, o filtre la lista por área. Al seleccionarlo verá sus datos y la pestaña "Evaluación con IA". El Administrador de RH da de alta talentos en "Nuevo talento", los edita, los da de baja con un motivo y los evalúa con el botón "Evaluar" (hay un número limitado de evaluaciones por talento al día). El Encargado de área consulta los talentos de su área y puede solicitar una corrección de datos o una reevaluación con IA.', '2026-10-11 21:23:47', 76, NULL),
    (40, 'Administrador RH', 'Talentos', 'Apartado "Lista"', '2026-10-11 17:35:12', 76, NULL),
    (44, 'Administrador RH', 'Talentos', 'Apartado "Nuevo talento"', '2026-10-11 20:27:07', 76, NULL),
    (45, 'Administrador RH', 'Talentos', 'Apartado "Talentos dados de baja"', '2026-10-11 20:28:13', 76, NULL),
    (46, 'Administrador RH', 'Notificaciones', 'Apartado "Bandeja"', '2026-10-11 20:33:43', 76, NULL),
    (47, 'Administrador RH', 'Notificaciones', 'Apartado "Nueva notificación"', '2026-10-11 20:35:15', 76, NULL),
    (48, 'Administrador RH', 'Notificaciones', 'Apartado "Alertas"', '2026-10-11 20:35:40', 76, NULL),
    (49, 'Administrador RH', 'Gestión de usuarios', 'Apartado "Usuarios"', '2026-10-11 20:41:18', 76, NULL),
