    (2168, 76, '2026-10-11 21:28:37', 'edicion', 'Manuales', 26, '{"dirigido_a": "Encargado de area", "seccion_software": "Notificaciones", "contenido_texto": "En \\"Bandeja\\" consulte sus notificaciones y su estado. En \\"Nueva notificación\\" elija el tipo, el talento (opcional), el grado de emergencia y escriba el texto. En \\"Alertas\\" configure reglas que generan", "contenido_enlace": null, "imagenes": 4}'),
    (2169, 76, '2026-10-11 21:29:14', 'edicion', 'Manuales', 27, '{"dirigido_a": "Encargado de area", "seccion_software": "Configuración", "contenido_texto": "Cambie su contraseña, el tema claro u oscuro, consulte el contacto de soporte o cierre sesión. El Administrador de RH además gestiona usuarios, parámetros del sistema, manuales y consulta la bitácora.", "contenido_enlace": null, "imagenes": 2}'),
    (2170, 76, '2026-10-11 21:30:20', 'edicion', 'Manuales', 27, '{"dirigido_a": "Encargado de area", "seccion_software": "Configuración", "contenido_texto": "Cambie su foto de perfil (No mayor a 5MB), contraseña, el tema claro u oscuro, consulte el contacto de soporte o cierre sesión. El Administrador de RH además gestiona usuarios, parámetros del sistema,", "contenido_enlace": null, "imagenes": 2}'),
